python3 -c "import json,sys,re
try:
 d=json.load(sys.stdin)
except Exception:
 sys.exit(0)
if d.get('stop_hook_active'): sys.exit(0)
p=d.get('transcript_path') or ''
last=''
try:
 for line in open(p):
  line=line.strip()
  if not line: continue
  try:
   o=json.loads(line)
  except Exception:
   continue
  if o.get('type')=='assistant':
   c=o.get('message',{}).get('content',[])
   txt=''.join(x.get('text','') for x in c if isinstance(x,dict) and x.get('type')=='text')
   if txt.strip(): last=txt
except Exception:
 sys.exit(0)
bad=[L.strip() for L in last.splitlines() if re.search(r'§ ?8|section 8',L.lower()) and 'raid-composition-guide' not in L.lower() and 'target spec ranges' not in L.lower()]
if bad:
 sys.stderr.write('Stop blocked: your reply uses a bare §8 / Section 8 as the table name. Use the canonical name target spec ranges (CLAUDE.md Communication conventions). A bare §8 is allowed only in a cross-reference naming reference/raid-composition-guide.md. Rewrite: '+' || '.join(bad))
 sys.exit(2)
sys.exit(0)"
